//! Simple Two-Body Kepler Orbit Validation
//!\n//! This test validates circular and elliptical orbit accuracy against analytical\n//! Kepler solutions with <1e-8 error tolerance using the correct Gravwell API.\n\nuse gravwell::prelude::*;\nuse std::f64::consts::PI;\n\n/// Constants for validation tests\nmod constants {\n    pub const G: f64 = 6.67430e-11;              // Gravitational constant (m³/kg⋅s²)\n    pub const SOLAR_MASS: f64 = 1.98847e30;      // Solar mass (kg)\n    pub const EARTH_MASS: f64 = 5.97219e24;      // Earth mass (kg)\n    pub const AU: f64 = 1.495978707e11;          // Astronomical unit (m)\n}\n\n/// Calculate theoretical circular orbital velocity\nfn circular_velocity(radius: f64, central_mass: f64) -> f64 {\n    (constants::G * central_mass / radius).sqrt()\n}\n\n/// Calculate theoretical orbital period using Kepler's third law\nfn orbital_period(semi_major_axis: f64, total_mass: f64) -> f64 {\n    2.0 * PI * (semi_major_axis.powi(3) / (constants::G * total_mass)).sqrt()\n}\n\n/// Assert relative error is within tolerance\nfn assert_relative_error(actual: f64, expected: f64, tolerance: f64, description: &str) {\n    let relative_error = (actual - expected).abs() / expected.abs().max(1e-100);\n    assert!(\n        relative_error <= tolerance,\n        \"{}: relative error {:.2e} exceeds tolerance {:.2e} (actual: {:.6e}, expected: {:.6e})\",\n        description, relative_error, tolerance, actual, expected\n    );\n}\n\n/// Create a simple Sun-Earth system for testing\nfn create_sun_earth_system() -> (SimulationBuilder<VelocityVerlet, DirectGravity>, BodyHandle, BodyHandle) {\n    let mut builder = SimulationBuilder::new()\n        .with_integrator(VelocityVerlet::new())\n        .with_force_calculator(DirectGravity::new());\n    \n    // Add Sun at origin\n    let sun = builder.add_body(Body::new()\n        .with_mass(constants::SOLAR_MASS)\n        .with_position([0.0, 0.0, 0.0])\n        .with_velocity([0.0, 0.0, 0.0])\n    ).expect(\"Failed to add Sun\");\n    \n    // Add Earth at 1 AU with circular orbital velocity\n    let earth_orbital_velocity = circular_velocity(constants::AU, constants::SOLAR_MASS);\n    let earth = builder.add_body(Body::new()\n        .with_mass(constants::EARTH_MASS)\n        .with_position([constants::AU, 0.0, 0.0])\n        .with_velocity([0.0, earth_orbital_velocity, 0.0])\n    ).expect(\"Failed to add Earth\");\n    \n    (builder, sun, earth)\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n\n    #[test]\n    fn test_circular_orbit_basic() {\n        println!(\"\\n🌍 Testing Earth circular orbit stability...\");\n        \n        let (mut builder, _sun, earth) = create_sun_earth_system();\n        let mut sim = builder.build().expect(\"Failed to build simulation\");\n        \n        // Calculate expected values\n        let expected_period = orbital_period(constants::AU, constants::SOLAR_MASS + constants::EARTH_MASS);\n        let expected_velocity = circular_velocity(constants::AU, constants::SOLAR_MASS);\n        \n        println!(\"Expected orbital period: {:.1} days\", expected_period / 86400.0);\n        println!(\"Expected orbital velocity: {:.1} m/s\", expected_velocity);\n        \n        // Get initial conditions\n        let initial_pos = sim.position(earth).expect(\"Earth should exist\");\n        let initial_vel = sim.velocity(earth).expect(\"Earth should exist\");\n        let initial_energy = sim.total_energy();\n        \n        // Validate initial setup\n        assert_relative_error(\n            initial_pos.norm(),\n            constants::AU,\n            1e-10,\n            \"Initial position at 1 AU\"\n        );\n        \n        assert_relative_error(\n            initial_vel.norm(),\n            expected_velocity,\n            1e-8,\n            \"Initial circular orbital velocity\"\n        );\n        \n        // Simulate for 1/4 orbit (about 3 months)\n        let timestep = 3600.0; // 1 hour\n        let quarter_orbit_steps = (expected_period / 4.0 / timestep) as usize;\n        \n        println!(\"Simulating {} steps ({} days)...\", quarter_orbit_steps, quarter_orbit_steps as f64 * timestep / 86400.0);\n        \n        for step in 0..quarter_orbit_steps {\n            sim.step(timestep).expect(\"Simulation step should succeed\");\n            \n            // Check every 100 steps\n            if step % 100 == 0 {\n                let current_pos = sim.position(earth).expect(\"Earth should exist\");\n                let current_distance = current_pos.norm();\n                \n                // Distance should remain approximately at 1 AU for circular orbit\n                let distance_error = (current_distance - constants::AU).abs() / constants::AU;\n                assert!(\n                    distance_error < 1e-6,\n                    \"Orbital distance drift at step {}: {:.2e}\",\n                    step, distance_error\n                );\n            }\n        }\n        \n        // Check final conditions after 1/4 orbit\n        let final_pos = sim.position(earth).expect(\"Earth should exist\");\n        let final_vel = sim.velocity(earth).expect(\"Earth should exist\");\n        let final_energy = sim.total_energy();\n        \n        // For 1/4 circular orbit, Earth should be at (0, 1 AU, 0) approximately\n        let expected_final_pos = Vector3::new(0.0, constants::AU, 0.0);\n        let position_error = (final_pos - expected_final_pos).norm() / constants::AU;\n        \n        println!(\"Final position: [{:.3e}, {:.3e}, {:.3e}] m\", final_pos.x, final_pos.y, final_pos.z);\n        println!(\"Expected position: [{:.3e}, {:.3e}, {:.3e}] m\", expected_final_pos.x, expected_final_pos.y, expected_final_pos.z);\n        println!(\"Position error: {:.3e} (relative to AU)\", position_error);\n        \n        assert!(\n            position_error < 1e-4, // Allow 0.01% error for discrete timesteps\n            \"Position error after 1/4 orbit: {:.2e}\",\n            position_error\n        );\n        \n        // Energy conservation\n        let energy_drift = (final_energy - initial_energy).abs() / initial_energy.abs();\n        println!(\"Energy drift: {:.3e}\", energy_drift);\n        \n        assert!(\n            energy_drift < 1e-8,\n            \"Energy conservation over 1/4 orbit: {:.2e}\",\n            energy_drift\n        );\n        \n        println!(\"✅ Circular orbit validation passed!\");\n    }\n\n    #[test] \n    fn test_kepler_third_law_simple() {\n        println!(\"\\n🪐 Testing Kepler's third law: T² ∝ a³...\");\n        \n        // Test different orbital distances\n        let distances = vec![\n            (0.5 * constants::AU, \"0.5 AU (Venus-like)\"),\n            (1.0 * constants::AU, \"1.0 AU (Earth)\"),\n            (1.5 * constants::AU, \"1.5 AU (Mars-like)\"),\n        ];\n        \n        let mut periods = Vec::new();\n        \n        for (distance, description) in &distances {\n            let period = orbital_period(*distance, constants::SOLAR_MASS + constants::EARTH_MASS);\n            periods.push(period);\n            \n            println!(\"  {}: {:.1} days\", description, period / 86400.0);\n            \n            // Verify theoretical relationship T² = (4π²/GM) * a³\n            let theoretical_t_squared = (4.0 * PI * PI / (constants::G * constants::SOLAR_MASS)) * distance.powi(3);\n            let calculated_t_squared = period * period;\n            \n            assert_relative_error(\n                calculated_t_squared,\n                theoretical_t_squared,\n                1e-12,\n                &format!(\"Kepler's third law at {}\", description)\n            );\n        }\n        \n        // Test proportionality: T₁²/T₀² should equal (a₁/a₀)³\n        let period_ratio_squared = (periods[2] / periods[0]).powi(2); // 1.5 AU / 0.5 AU\n        let distance_ratio_cubed = (1.5 / 0.5_f64).powi(3); // Should be 27\n        \n        assert_relative_error(\n            period_ratio_squared,\n            distance_ratio_cubed,\n            1e-12,\n            \"Kepler's third law proportionality\"\n        );\n        \n        println!(\"  Period ratio²: {:.6}\", period_ratio_squared);\n        println!(\"  Distance ratio³: {:.6}\", distance_ratio_cubed);\n        println!(\"✅ Kepler's third law validation passed!\");\n    }\n    \n    #[test]\n    fn test_vis_viva_equation() {\n        println!(\"\\n⚡ Testing vis-viva equation: v² = μ(2/r - 1/a)...\");\n        \n        let (mut builder, _sun, earth) = create_sun_earth_system();\n        let mut sim = builder.build().expect(\"Failed to build simulation\");\n        \n        let mu = constants::G * constants::SOLAR_MASS; // Standard gravitational parameter\n        let semi_major_axis = constants::AU; // For circular orbit, a = r\n        \n        // Test vis-viva equation at multiple points in orbit\n        let timestep = 7200.0; // 2 hours\n        let num_checks = 50;\n        \n        for i in 0..num_checks {\n            if i > 0 {\n                sim.step(timestep).expect(\"Simulation step should succeed\");\n            }\n            \n            let pos = sim.position(earth).expect(\"Earth should exist\");\n            let vel = sim.velocity(earth).expect(\"Earth should exist\");\n            \n            let r = pos.norm();\n            let v_squared = vel.norm_squared();\n            \n            // Apply vis-viva equation: v² = μ(2/r - 1/a)\n            let expected_v_squared = mu * (2.0 / r - 1.0 / semi_major_axis);\n            \n            assert_relative_error(\n                v_squared,\n                expected_v_squared,\n                1e-10,\n                &format!(\"Vis-viva equation at check {}\", i + 1)\n            );\n            \n            if i % 10 == 0 {\n                println!(\"  Check {}: r={:.3e}m, v²={:.1e}m²/s², expected={:.1e}m²/s²\", \n                    i + 1, r, v_squared, expected_v_squared);\n            }\n        }\n        \n        println!(\"✅ Vis-viva equation validation passed!\");\n    }\n}\n\n/// Run all Kepler validation tests\npub fn run_kepler_validation() {\n    println!(\"\\n═══════════════════════════════════\");\n    println!(\"   GRAVWELL KEPLER VALIDATION\");\n    println!(\"═══════════════════════════════════\");\n    \n    println!(\"To run Kepler orbit validation tests:\");\n    println!(\"  cargo test kepler_validation::test_circular_orbit_basic\");\n    println!(\"  cargo test kepler_validation::test_kepler_third_law_simple\");\n    println!(\"  cargo test kepler_validation::test_vis_viva_equation\");\n    \n    println!(\"\\nOr run all validation tests:\");\n    println!(\"  cargo test kepler_validation\");\n}\n
